import{_ as d,H as r,f as e,i as a}from"./chunks/framework.nyB-Xt5O.js";const u=JSON.parse('{"title":"📖 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/ap-2-glossary.md","filePath":"appendix/ap-2-glossary.md","lastUpdated":1779798726000}'),o={name:"appendix/ap-2-glossary.md"};function n(s,t,h,i,g,l){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="📖-术语表" tabindex="-1">📖 术语表 <a class="header-anchor" href="#📖-术语表" aria-label="Permalink to &quot;📖 术语表&quot;">​</a></h1><blockquote><p>BI / 数据分析领域常用中英文术语解释，按字母序排列。每个条目包含中文名称、英文全称与简要说明。</p></blockquote><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>AARRR 模型</strong></td><td>Acquisition - Activation - Retention - Revenue - Referral</td><td>海盗指标，用户生命周期分析的经典框架。分别对应：用户获取、激活、留存、收入、自传播</td></tr><tr><td><strong>AB 测试 (A/B Testing)</strong></td><td>—</td><td>随机分流实验，将用户分为实验组和对照组，比较不同版本的差异以验证假设</td></tr><tr><td><strong>ACP</strong></td><td>Average Collection Period</td><td>平均回款周期，反映企业应收账款回收效率的指标</td></tr><tr><td><strong>Ad-hoc 分析</strong></td><td>—</td><td>临时性、一次性的数据分析请求，通常由业务方紧急提出</td></tr><tr><td><strong>API</strong></td><td>Application Programming Interface</td><td>应用程序编程接口，数据工具之间通信的标准化方式</td></tr><tr><td><strong>ARIMA</strong></td><td>Autoregressive Integrated Moving Average</td><td>自回归积分滑动平均模型，用于时间序列预测的经典统计方法</td></tr><tr><td><strong>ARPDAU</strong></td><td>Average Revenue Per Daily Active User</td><td>每活跃用户日均收入 = 日总收入 / DAU</td></tr><tr><td><strong>ARPPU</strong></td><td>Average Revenue Per Paying User</td><td>每付费用户平均收入 = 总收入 / 付费用户数</td></tr><tr><td><strong>ARPU</strong></td><td>Average Revenue Per User</td><td>每用户平均收入 = 总收入 / 用户总数（含非付费用户）</td></tr><tr><td><strong>AUC</strong></td><td>Area Under the ROC Curve</td><td>ROC 曲线下面积，衡量二分类模型区分能力的综合指标，AUC=1 为完美，AUC=0.5 为随机</td></tr></tbody></table><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>BI</strong></td><td>Business Intelligence</td><td>商业智能，通过数据分析和可视化工具辅助业务决策的体系</td></tr><tr><td><strong>BIA</strong></td><td>Business Impact Analysis</td><td>业务影响分析，评估数据问题对业务造成的影响程度</td></tr><tr><td><strong>Bootstrap</strong></td><td>—</td><td>自助法，通过对样本有放回地重复抽样来估计统计量分布的非参数方法</td></tr><tr><td><strong>BQ</strong></td><td>BigQuery</td><td>Google Cloud 的 Serverless 数据仓库服务，支持标准 SQL</td></tr></tbody></table><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>CAC</strong></td><td>Customer Acquisition Cost</td><td>客户获取成本 = 总营销费用 / 新增客户数</td></tr><tr><td><strong>CAGR</strong></td><td>Compound Annual Growth Rate</td><td>复合年增长率 = (终值/初值)^(1/n) - 1</td></tr><tr><td><strong>Cardinality</strong></td><td>—</td><td>基数，指某列中不重复值的数量。高基数列（如用户ID）的聚合和索引策略不同于低基数列（如性别）</td></tr><tr><td><strong>CDP</strong></td><td>Customer Data Platform</td><td>客户数据平台，整合多渠道客户数据构建统一用户画像的系统</td></tr><tr><td><strong>Churn Rate</strong></td><td>—</td><td>流失率，一段时间内停止使用产品的用户比例。月流失率 = 当月流失用户数 / 月初用户数</td></tr><tr><td><strong>CLV / LTV</strong></td><td>Customer Lifetime Value</td><td>用户生命周期价值，一个用户从开始到结束使用产品期间贡献的总收入</td></tr><tr><td><strong>Cohort 分析</strong></td><td>—</td><td>同期群分析，将用户按首次行为时间分组，跟踪各组后续表现，消除时间偏移效应</td></tr><tr><td><strong>CPI / CPA</strong></td><td>Cost Per Install / Cost Per Acquisition</td><td>每安装成本 / 每获取成本，移动应用推广中常用的计费方式</td></tr><tr><td><strong>CSV</strong></td><td>Comma-Separated Values</td><td>逗号分隔值，最通用的数据交换格式之一，简单但缺乏数据类型信息</td></tr><tr><td><strong>CTE</strong></td><td>Common Table Expression</td><td>公用表表达式，SQL 中使用 WITH 子句定义的临时命名结果集，提高复杂查询的可读性</td></tr><tr><td><strong>CTR</strong></td><td>Click-Through Rate</td><td>点击率 = 点击次数 / 展示次数。衡量广告或推荐效果的基础指标</td></tr></tbody></table><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>—</td><td>仪表盘，将关键指标可视化集中展示的页面，服务于监控和决策场景</td></tr><tr><td><strong>DAU / MAU / WAU</strong></td><td>Daily / Monthly / Weekly Active Users</td><td>日/月/周活跃用户数，衡量用户规模的三个核心指标</td></tr><tr><td><strong>DID</strong></td><td>Difference-in-Differences</td><td>双重差分法，利用自然实验通过比较处理组与对照组的前后变化来估计因果效应</td></tr><tr><td><strong>Dirty Data</strong></td><td>—</td><td>脏数据，包含错误、缺失、不一致等质量问题的数据</td></tr><tr><td><strong>DM</strong></td><td>Data Mart</td><td>数据集市，面向特定业务主题的轻量级数据仓库子集</td></tr><tr><td><strong>DML / DDL / DQL</strong></td><td>Data Manipulation / Definition / Query Language</td><td>SQL 子语言分类：DML 操作数据 (INSERT/UPDATE/DELETE), DDL 定义结构 (CREATE/ALTER), DQL 查询 (SELECT)</td></tr><tr><td><strong>DQC</strong></td><td>Data Quality Center / Check</td><td>数据质量中心 / 数据质量检查，保障数据准确性和完整性的流程体系</td></tr><tr><td><strong>DWH</strong></td><td>Data Warehouse</td><td>数据仓库，面向分析的集中化数据存储系统，支持历史数据整合和复杂查询</td></tr></tbody></table><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>ELT / ETL</strong></td><td>Extract, Load, Transform / Extract, Transform, Load</td><td>数据集成流程：ELT 先加载再转换（现代数仓），ETL 先转换再加载（传统数仓）</td></tr><tr><td><strong>ETL 测试</strong></td><td>—</td><td>验证 ETL 流程数据完整性的过程，包括行数对比、字段级校验、异常值检查等</td></tr><tr><td><strong>Event 埋点</strong></td><td>—</td><td>在应用中嵌入采集代码，追踪用户行为事件（如点击、浏览、购买），是用户行为数据的主要来源</td></tr></tbody></table><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Fact Table</strong></td><td>—</td><td>事实表，存储业务事件或交易的度量数据，通常包含外键和数值型指标，行数快速增长</td></tr><tr><td><strong>Funnel 分析</strong></td><td>—</td><td>漏斗分析，追踪用户在多个步骤间的转化率，定位流失关键环节</td></tr><tr><td><strong>FPR / TPR</strong></td><td>False Positive Rate / True Positive Rate</td><td>假正率 (=FP/(FP+TN)) 与真正率 (=TP/(TP+FN))，ROC 曲线的横纵坐标</td></tr></tbody></table><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>GA / GA4</strong></td><td>Google Analytics / Google Analytics 4</td><td>网站/应用分析工具，GA4 是新一代以事件为核心的分析平台</td></tr><tr><td><strong>GMV</strong></td><td>Gross Merchandise Volume</td><td>商品交易总额，电商平台统计的成交总金额（含未支付、退货等）</td></tr><tr><td><strong>GCP</strong></td><td>Google Cloud Platform</td><td>Google 云平台，提供 BigQuery、Dataflow、Pub/Sub 等数据服务</td></tr><tr><td><strong>Granularity</strong></td><td>—</td><td>粒度，数据表中每行所代表的最小单位。如&quot;日粒度&quot;一行代表一天，&quot;用户粒度&quot;一行代表一个用户</td></tr></tbody></table><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>HLL</strong></td><td>HyperLogLog</td><td>近似去重计数算法，以少量精度损失换取极低内存占用，广泛用于 UV 估算</td></tr><tr><td><strong>HDFS</strong></td><td>Hadoop Distributed File System</td><td>Hadoop 分布式文件系统，大数据存储的基础组件</td></tr><tr><td><strong>Hive</strong></td><td>—</td><td>基于 Hadoop 的数据仓库工具，将 SQL 转化为 MapReduce 任务执行</td></tr></tbody></table><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>IQR</strong></td><td>Interquartile Range</td><td>四分位距 (Q3 - Q1)，用于箱线图的异常值检测</td></tr><tr><td><strong>ISO 时间</strong></td><td>—</td><td>ISO 8601 日期时间格式，如 <code>2026-05-26T14:30:00+08:00</code>，数据交换中的标准时间格式</td></tr><tr><td><strong>ITR</strong></td><td>Inventory Turnover Ratio</td><td>库存周转率 = 销售成本 / 平均库存，衡量库存管理效率</td></tr></tbody></table><h2 id="k" tabindex="-1">K <a class="header-anchor" href="#k" aria-label="Permalink to &quot;K&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>KPI</strong></td><td>Key Performance Indicator</td><td>关键绩效指标，衡量业务目标达成情况的量化指标，遵循 SMART 原则</td></tr><tr><td><strong>KRI</strong></td><td>Key Risk Indicator</td><td>关键风险指标，用于监控业务风险的先行预警指标</td></tr></tbody></table><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>LAG / LEAD</strong></td><td>—</td><td>SQL 窗口函数，LAG 获取前 N 行值，LEAD 获取后 N 行值，常用于同环比计算</td></tr><tr><td><strong>LTV / CLV</strong></td><td>Lifetime Value</td><td>用户生命周期价值（见 C 组 CLV 条目）</td></tr></tbody></table><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>MAU</strong></td><td>Monthly Active Users</td><td>月活跃用户数，通常指自然月内至少有一次有效行为的独立用户数</td></tr><tr><td><strong>MDE</strong></td><td>Minimum Detectable Effect</td><td>最小可检测效应，AB 实验中给定样本量和显著性水平下能可靠检测到的最小效果大小</td></tr><tr><td><strong>Metrics</strong></td><td>—</td><td>度量指标，对业务活动的量化描述。好的指标应具备可衡量、可行动、相关性等特征</td></tr><tr><td><strong>MPP</strong></td><td>Massively Parallel Processing</td><td>大规模并行处理架构，现代分析型数据库（如 ClickHouse、Greenplum）的典型架构</td></tr><tr><td><strong>MRR / ARR</strong></td><td>Monthly / Annual Recurring Revenue</td><td>月/年经常性收入，SaaS 行业核心指标，衡量订阅收入的稳定性和增长</td></tr><tr><td><strong>MSE / MAE / RMSE</strong></td><td>Mean Squared / Absolute / Root Mean Squared Error</td><td>回归模型预测误差的三种度量：MSE 放大离群值影响，MAE 对离群值更鲁棒，RMSE 与原始单位一致</td></tr></tbody></table><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>NPS</strong></td><td>Net Promoter Score</td><td>净推荐值，衡量用户忠诚度的指标 = 推荐者% - 贬损者%，范围 [-100, 100]</td></tr><tr><td><strong>NRR</strong></td><td>Net Revenue Retention</td><td>净收入留存率 = (期初收入 + 扩增收入 - 流失收入) / 期初收入，SaaS 健康度核心指标，NRR &gt; 100% 说明扩增超过流失</td></tr><tr><td><strong>NULL</strong></td><td>—</td><td>表示缺失值或未知值。SQL 中 NULL 不与任何值相等（包括自身），判断用 IS NULL 而非 = NULL</td></tr><tr><td><strong>NumPy</strong></td><td>—</td><td>Python 数值计算基础库，提供 N 维数组对象和线性代数函数，Pandas 的底层依赖</td></tr></tbody></table><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>ODS</strong></td><td>Operational Data Store</td><td>操作数据存储，近源层的贴源数据区，几乎不做业务逻辑转换</td></tr><tr><td><strong>OKR</strong></td><td>Objectives and Key Results</td><td>目标与关键成果法，设定定量目标和可衡量的关键结果以对齐团队方向</td></tr><tr><td><strong>OLAP / OLTP</strong></td><td>Online Analytical / Transaction Processing</td><td>OLAP 分析型（星型/雪花模型，批量查询），OLTP 事务型（3NF，高并发单行操作）</td></tr><tr><td><strong>Outlier</strong></td><td>—</td><td>异常值/离群点，显著偏离数据分布正常范围的观测值，需结合业务判断是否剔除</td></tr></tbody></table><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>p-value</strong></td><td>—</td><td>p 值，在原假设为真的条件下观察到当前结果或更极端结果的概率。p &lt; 0.05 通常认为统计显著</td></tr><tr><td><strong>Parquet</strong></td><td>—</td><td>列式存储格式，压缩率高、查询性能好，是大数据生态中首选的分析文件格式</td></tr><tr><td><strong>PCA</strong></td><td>Principal Component Analysis</td><td>主成分分析，通过正交变换将多个相关变量压缩为少数不相关的主成分，用于降维和可视化</td></tr><tr><td><strong>PSM</strong></td><td>Propensity Score Matching</td><td>倾向得分匹配，通过估计处理概率来匹配处理组和对照组的观察性研究因果推断方法</td></tr><tr><td><strong>Power BI</strong></td><td>—</td><td>Microsoft 的商业智能工具，支持自助式数据分析和仪表盘共享</td></tr><tr><td><strong>Presto / Trino</strong></td><td>—</td><td>分布式 SQL 查询引擎，支持对异构数据源（Hive、MySQL、Kafka 等）进行联邦查询</td></tr></tbody></table><h2 id="q" tabindex="-1">Q <a class="header-anchor" href="#q" aria-label="Permalink to &quot;Q&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Quantile</strong></td><td>—</td><td>分位数，将数据排序后等分为若干份的切分点。常用的有四分位数 (Q1/Q2/Q3)、十分位数、百分位数</td></tr><tr><td><strong>Query Optimization</strong></td><td>—</td><td>查询优化，通过调整 SQL 写法、索引策略和执行计划分析来提升查询性能</td></tr></tbody></table><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>R²</strong></td><td>R-Squared / Coefficient of Determination</td><td>决定系数，衡量回归模型拟合优度，范围 [0,1]，表示自变量解释因变量变异的比例</td></tr><tr><td><strong>RDD</strong></td><td>Regression Discontinuity Design</td><td>断点回归设计，利用某个门槛值附近的连续性假设进行因果推断的方法</td></tr><tr><td><strong>RFM</strong></td><td>Recency - Frequency - Monetary</td><td>基于最近消费时间、消费频率和消费金额三个维度的用户价值分层模型</td></tr><tr><td><strong>ROI</strong></td><td>Return on Investment</td><td>投资回报率 = (收益 - 成本) / 成本 × 100%，衡量投入产出效率</td></tr><tr><td><strong>Row-Level Security (RLS)</strong></td><td>—</td><td>行级安全，数据权限控制策略，确保用户只能看到其有权限的数据行</td></tr><tr><td><strong>RR</strong></td><td>Retention Rate</td><td>留存率，用户在首次行为后特定时间点仍在活跃的比例，通常有次日/7日/30日留存</td></tr></tbody></table><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>SCD</strong></td><td>Slowly Changing Dimension</td><td>缓慢变化维度，维度表中属性随时间变化的处理策略。Type 1 覆盖、Type 2 新增行、Type 3 新增列</td></tr><tr><td><strong>Schema</strong></td><td>—</td><td>数据模式 / 结构，描述数据库表、列、数据类型和关系的逻辑组织方式</td></tr><tr><td><strong>Segment 分析</strong></td><td>—</td><td>用户分群分析，根据行为或属性将用户划分为不同的细分群体以进行针对性分析</td></tr><tr><td><strong>SEM / SEO</strong></td><td>Search Engine Marketing / Optimization</td><td>搜索引擎营销/优化，前者为付费广告，后者为自然排名优化</td></tr><tr><td><strong>SLA / SLO</strong></td><td>Service Level Agreement / Objective</td><td>服务等级协议/目标，数据管道承诺的可用性和时效性指标</td></tr><tr><td><strong>Slow Query Log</strong></td><td>—</td><td>慢查询日志，记录执行时间超过阈值的 SQL 语句，是性能优化的重要切入点</td></tr><tr><td><strong>Snowflake Schema</strong></td><td>—</td><td>雪花模型，星型模型的扩展，将维度表进一步规范化拆分，减少数据冗余但增加查询复杂度</td></tr><tr><td><strong>Spark</strong></td><td>—</td><td>大数据统一分析引擎，支持批处理、流计算、SQL、ML 等多种工作负载</td></tr><tr><td><strong>SQL</strong></td><td>Structured Query Language</td><td>结构化查询语言，与关系型数据库交互的标准语言，数据分析师的核心技能</td></tr><tr><td><strong>SRM</strong></td><td>Sample Ratio Mismatch</td><td>样本比例不匹配，AB 实验中分流比例偏离设定的问题，通常表明实验系统或数据存在偏差</td></tr><tr><td><strong>Star Schema</strong></td><td>—</td><td>星型模型，事实表居中、周边连接多个维度表，是数据仓库建模中最常用的结构</td></tr><tr><td><strong>Statistical Power</strong></td><td>—</td><td>统计功效 = 1 - β (β 为第二类错误概率)，在效应存在时正确拒绝原假设的概率。通常要求 ≥ 0.8</td></tr></tbody></table><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Tableau</strong></td><td>—</td><td>业界领先的可视化分析工具，以拖拽式操作和丰富的图表类型著称</td></tr><tr><td><strong>Time-to-Conversion</strong></td><td>—</td><td>转化时长，用户从首次接触到完成目标行为（如下单）所经过的时间</td></tr><tr><td><strong>TMM</strong></td><td>Total Money Management</td><td>资金管理总额，互联网金融平台常见指标</td></tr><tr><td><strong>Tracking 规范</strong></td><td>—</td><td>数据埋点规范，定义事件命名、属性字段、采集时机等标准，保证数据采集的一致性和可用性</td></tr></tbody></table><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>UDAF</strong></td><td>User-Defined Aggregate Function</td><td>用户自定义聚合函数，当内置聚合函数无法满足需求时编写的自定义逻辑</td></tr><tr><td><strong>UDF</strong></td><td>User-Defined Function</td><td>用户自定义函数，扩展 SQL 能力的机制，支持自定义数据处理逻辑</td></tr><tr><td><strong>UV / PV</strong></td><td>Unique Visitors / Page Views</td><td>独立访客数 / 页面浏览量，网站分析中最基础的两个流量指标</td></tr><tr><td><strong>Uplift 模型</strong></td><td>—</td><td>增量模型 / 增益模型，预测某个动作为用户带来的增量效果，用于精准营销的 Treatment 选择</td></tr></tbody></table><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Variance Inflation Factor (VIF)</strong></td><td>—</td><td>方差膨胀因子，衡量多重共线性的严重程度，VIF &gt; 10 表示存在严重的共线性</td></tr><tr><td><strong>VLOOKUP</strong></td><td>—</td><td>Excel/VLookup (垂直查找函数)，用于在表格中按键值匹配查找数据，Pandas 中对应 <code>merge</code> 操作</td></tr></tbody></table><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Windowing Function</strong></td><td>—</td><td>窗口函数 / 开窗函数，在保持行数不变的前提下对数据集的行分组计算，广泛用于排名、累计、同环比等场景</td></tr><tr><td><strong>WIP</strong></td><td>Work In Progress</td><td>进行中的工作/在制品，项目管理中正在处理但尚未完成的任务或数据管道</td></tr></tbody></table><h2 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td><strong>Z-score</strong></td><td>—</td><td>标准分数 = (x - μ) / σ，表示数据点偏离均值多少个标准差，常用于异常值检测和标准化</td></tr><tr><td><strong>Z 检验</strong></td><td>Z-test</td><td>大样本 (n ≥ 30) 下均值或比例差异的显著性检验方法</td></tr></tbody></table><hr><h2 id="按分类索引" tabindex="-1">按分类索引 <a class="header-anchor" href="#按分类索引" aria-label="Permalink to &quot;按分类索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>相关术语</th></tr></thead><tbody><tr><td><strong>用户指标</strong></td><td>AARRR, ARPU, ARPPU, CAC, Churn Rate, CLV/LTV, Cohort, DAU/MAU/WAU, NPS, NRR, Retention, RFM, Segment</td></tr><tr><td><strong>财务指标</strong></td><td>ARPU, ARPPU, CAC, CAGR, CLV, GMV, MRR/ARR, ROI</td></tr><tr><td><strong>统计方法</strong></td><td>A/B Testing, ANOVA, Bootstrap, DID, p-value, PCA, PSM, RDD, Z 检验</td></tr><tr><td><strong>实验相关</strong></td><td>A/B Testing, MDE, SRM, Statistical Power, Uplift</td></tr><tr><td><strong>数据工程</strong></td><td>DWH, ETL/ELT, Fact Table, Hive, ODS, Parquet, SCD, Schema, Snowflake, Spark, Star Schema</td></tr><tr><td><strong>数据质量</strong></td><td>Dirty Data, DQC, SLA/SLO, SRM</td></tr><tr><td><strong>工具</strong></td><td>BI, BigQuery, Excel (VLOOKUP), GA4, Power BI, Presto, Spark, Tableau</td></tr><tr><td><strong>SQL 概念</strong></td><td>Cardinality, CTE, DML/DDL/DQL, LAG/LEAD, NULL, Query Optimization, UDF/UDAF, Windowing Function</td></tr></tbody></table>',52)])])}const c=d(o,[["render",n]]);export{u as __pageData,c as default};
